    private static JsonDocument Read()
    {
        using var input = new MemoryStream(Convert.FromBase64String(Corpus));
        using var gzip = new GZipStream(input,CompressionMode.Decompress);
        return JsonDocument.Parse(gzip);
    }
    public static IEnumerable<object[]> WireCases()
    {
        using var doc=Read();
        foreach(var row in doc.RootElement.GetProperty("cases").EnumerateArray())
            yield return new object[]{row.GetProperty("index").GetInt32(),row.GetProperty("payload").GetString()!};
    }
    private static P.Fields Input(int index=0)
    {
        using var doc=Read();var f=doc.RootElement.GetProperty("cases")[index].GetProperty("fields");
        uint U(string k)=>f.GetProperty(k).GetUInt32();
        byte B(string k)=>(byte)U(k);ushort H(string k)=>(ushort)U(k);
        RetailMainVectorWords Vector(string k)=>new(f.GetProperty(k)[0].GetUInt32(),f.GetProperty(k)[1].GetUInt32(),f.GetProperty(k)[2].GetUInt32());
        string? text=f.GetProperty("master").ValueKind==JsonValueKind.Null?null:
            new string(f.GetProperty("master").EnumerateArray().Select(v=>(char)v.GetInt32()).ToArray());
        return new(Vector("position"),U("object"),U("npc"),U("visual"),B("type"),H("state"),B("heading"),
            U("name"),U("title"),U("creator"),text,B("hp"),f.GetProperty("maxhp").GetInt32(),B("level"),
            f.GetProperty("gear").EnumerateArray().Select(e=>new P.GearEntry(e[0].GetUInt64(),e[1].GetUInt32())).ToImmutableArray(),
            U("radius"),U("height"),U("speed"),H("mainDelay"),H("offDelay"),B("spawn"),Vector("goal"),B("move"),H("static"),
            B("visualState"),H("objectType"),U("target"),U("town"));
    }
    [Theory] [MemberData(nameof(WireCases))]
    public void CompleteBodyMatchesIndependentJava48GrammarIncludingRetainedGolden(int index,string expectedHex)
    {
        var result=P.Calculate(Input(index));Assert.Equal(P.Status.Encoded,result.Status);Assert.Null(result.Failure);
        Assert.Equal(Convert.FromHexString(expectedHex),result.Bytes.ToArray());
        var packet=result.CreatePacket();Assert.Equal(14,packet.GetOpCode());
        Assert.Equal(result.Bytes.ToArray(),Capture(packet));
        Assert.False(result.CertifiesGameplay);Assert.False(result.CanApplyToHost);Assert.False(result.ActivationReady);
    }
    public static IEnumerable<object[]> SingleSlots()
    {
        foreach(int bit in Enumerable.Range(0,20).Concat(Enumerable.Range(30,6)))yield return new object[]{bit};
    }
    [Theory] [MemberData(nameof(SingleSlots))]
    public void SingleSlotMaskRetainsJavaNarrowingAndOneCompleteGearRow(int bit)
    {
        var f=Input() with {MasterName=null,Equipment=[new(1UL<<bit,0x12345678)]};
        var result=P.Calculate(f);Assert.Equal(P.Status.Encoded,result.Status);Assert.Equal(131,result.Bytes.Length);
        Assert.Equal(unchecked((uint)(1UL<<bit)),System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(result.Bytes.AsSpan(55,4)));
        Assert.Equal("78563412000000000000000000000000",Convert.ToHexStringLower(result.Bytes.AsSpan(59,16)));
    }
    [Theory] [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)] [InlineData(4)] [InlineData(5)]
    public void UnknownDuplicateCompositeOutOfOrderOrExcessEquipmentHasNoPacket(int variant)
    {
        var f=Input() with {Equipment=variant switch {
            0=>default,1=>[new(0,1)],2=>[new(3,1)],3=>[new(1,1),new(1,2)],
            4=>[new(2,1),new(1,2)],_=>Enumerable.Repeat(new P.GearEntry(1,1),27).ToImmutableArray()}};
        var result=P.Calculate(f);Assert.Equal(P.Status.InvalidEquipment,result.Status);Assert.Empty(result.Bytes);
        Assert.Throws<InvalidOperationException>(()=>result.CreatePacket());
    }
    [Fact]
    public void NullEquipmentMemberAndUnknownSingleSlotAreVisibleFailures()
    {
        foreach(var gear in new[]{ImmutableArray.Create<P.GearEntry>((P.GearEntry)null!),ImmutableArray.Create(new P.GearEntry(1UL<<29,1))})
            Assert.Equal(P.Status.InvalidEquipment,P.Calculate(Input() with {Equipment=gear}).Status);
    }
    [Theory] [InlineData(0x00000000u)] [InlineData(0x80000000u)] [InlineData(0x00000001u)]
    [InlineData(0x7fc12345u)] [InlineData(0x7f800000u)] [InlineData(0xff800000u)]
    public void AllFloatWordsAreCopiedExactlyWithoutMath(uint word)
    {
        var f=Input() with {MasterName=null,Equipment=[],Position=new(word,word,word),Goal=new(word,word,word),RadiusWord=word,HeightWord=word,MovementSpeedWord=word};
        var bytes=P.Calculate(f).Bytes;
        foreach(int offset in new[]{0,4,8,59,63,67,76,80,84})
            Assert.Equal(word,System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(offset,4)));
    }
    [Fact]
    public void ExactExistingClientFrameLimitIsAcceptedAndNextUnitIsRejectedWithoutPartialBytes()
    {
        var f=Input() with {MasterName=new string('x',4035),Equipment=[]};
        var complete=P.Calculate(f);Assert.Equal(P.Status.Encoded,complete.Status);
        Assert.Equal(AionServerPacket.MAX_USABLE_PACKET_BODY_SIZE,complete.Bytes.Length);
        var tooBig=P.Calculate(f with {MasterName=f.MasterName+"x"});Assert.Equal(P.Status.PacketTooLarge,tooBig.Status);
        Assert.Empty(tooBig.Bytes);Assert.Throws<InvalidOperationException>(()=>tooBig.CreatePacket());
    }
    [Fact]
    public void PacketHasNoCreatureReferenceAndRepeatedWritesDoNotReadMutatedCopies()
    {
        var result=P.Calculate(Input(25));var packet=result.CreatePacket();var first=Capture(packet);first[0]^=255;
        var copy=result.Bytes.ToArray();copy[1]^=255;
        Assert.Equal(result.Bytes.ToArray(),Capture(packet));
        Assert.DoesNotContain(packet.GetType().GetFields(BindingFlags.Instance|BindingFlags.NonPublic),
            x=>typeof(Aion.GameServer.Model.GameObjects.VisibleObject).IsAssignableFrom(x.FieldType));
    }
    private static byte[] Capture(AionServerPacket packet)
    {
        var buffer=ByteBuffer.Allocate(8192).Order(ByteOrder.LITTLE_ENDIAN);packet.SetBuf(buffer);
        typeof(AionServerPacket).GetMethod("WriteImpl",BindingFlags.Instance|BindingFlags.NonPublic,new[]{typeof(AionConnection)})!
            .Invoke(packet,new object?[]{null});
        byte[] bytes=new byte[buffer.Position()];buffer.Flip();buffer.Get(bytes);return bytes;
    }
